pjson_align.jq
pjson_align_README.md
=== the filter ===
def w: tostring | length;
def sp($n): " " * $n;
def isbox: type == "object" or type == "array";
def emit($ind; $depth):
  if type == "object" then
    ( [ keys_unsorted[] | w ] | max // 0 ) as $kw
    | . as $o
    | [ keys_unsorted[] as $k
        | sp($ind) + ($k | tojson) + sp($kw - ($k | w) + 2) + ":"
          + ( if $depth > 0 and ($o[$k] | isbox)
              then "\n" + ($o[$k] | emit($ind + $kw + 4; $depth - 1))
              else " " + ($o[$k] | tostring) end )
      ] | join("\n")
  elif type == "array" then
    . as $a
    | [ to_entries[] as $e
        | sp($ind) + "-"
          + ( if $depth > 0 and ($e.value | isbox)
              then "\n" + ($e.value | emit($ind + 2; $depth - 1))
              else " " + ($e.value | tostring) end ) ] | join("\n")
  else tostring end;
if isbox then emit(0; 3) else tostring end

